  "claim_id": "C055",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C055.main",
    "value": "Concurrent changes can leave the release effect uncertain.",
    "scope": "A possible limitation, not a finding that concurrent changes occurred.",
    "provenance": {
      "refs": [
