          "source_id": "P026",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly identifies concurrent changes as a possible source of uncertainty about the release effect."
    }
  },
  "signal_basis": {
    "component_id": "C055.signal_basis",
    "value": "Observe whether first-publication proportions change within the predefined window. Interpreting a publication difference as an effect requires valid random assignment, comparable follow-up and reliable outcome capture; concurrent changes may leave that effect uncertain.",
    "scope": "Proposed post-release observations, assumed to occur for this judgment; no finding that concurrent changes actually occurred.",
    "provenance": {
      "refs": [
